create schema if not exists privado;
revoke all on schema privado from public,anon,authenticated;
grant usage on schema privado to authenticated;
create table public.perfiles(id uuid primary key references auth.users(id) on delete cascade,nombre text not null default '',avatar_path text,rol text not null default 'cliente' check(rol in ('cliente','admin')),activo boolean not null default true, creado_en timestamptz not null default now());
alter table public.perfiles enable row level security;
revoke all on public.perfiles from anon,authenticated;
grant select on public.perfiles to authenticated;
grant update(nombre,avatar_path) on public.perfiles to authenticated;
create function privado.es_admin() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.perfiles where id=auth.uid() and rol='admin' and activo) $$;
revoke all on function privado.es_admin() from public;
grant execute on function privado.es_admin() to authenticated;
create function privado.activo() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.perfiles where id=auth.uid() and activo) $$;
revoke all on function privado.activo() from public;
grant execute on function privado.activo() to authenticated;
create policy perfil_lectura on public.perfiles for select to authenticated using(id=(select auth.uid()) or (select privado.es_admin()));
create policy perfil_edicion on public.perfiles for update to authenticated using(id=(select auth.uid()) and (select privado.activo())) with check(id=(select auth.uid()) and (select privado.activo()));
create function privado.nuevo_usuario() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.perfiles(id,nombre) values(new.id,left(coalesce(new.raw_user_meta_data->>'nombre',''),120)); return new; end $$;
revoke all on function privado.nuevo_usuario() from public,anon,authenticated;
create trigger tharpon_nuevo_usuario after insert on auth.users for each row execute function privado.nuevo_usuario();
insert into public.perfiles(id) select id from auth.users on conflict do nothing;
;
